import json
import base64
import hashlib
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad

# AES-CBC decryption service for inter-service token validation
# Used by internal microservices to decrypt session tokens

SECRET_KEY = None

def get_encryption_key():
    global SECRET_KEY
    if SECRET_KEY is None:
        # In production, fetched from AWS Secrets Manager
        import boto3
        client = boto3.client('secretsmanager')
        response = client.get_secret_value(SecretId='token-encryption-key')
        SECRET_KEY = base64.b64decode(response['SecretString'])
    return SECRET_KEY


def decrypt_token(ciphertext_b64):
    """Decrypt an AES-CBC encrypted token.
    Format: IV (16 bytes) || ciphertext
    Returns plaintext bytes or raises specific exceptions.
    """
    raw = base64.b64decode(ciphertext_b64)
    if len(raw) < 32:
        raise ValueError("Ciphertext too short")

    iv = raw[:16]
    ciphertext = raw[16:]

    if len(ciphertext) % 16 != 0:
        raise ValueError("Invalid ciphertext length")

    key = get_encryption_key()
    cipher = AES.new(key, AES.MODE_CBC, iv)
    plaintext_padded = cipher.decrypt(ciphertext)

    # PKCS7 unpadding - raises ValueError on invalid padding
    plaintext = unpad(plaintext_padded, AES.block_size)
    return plaintext


def validate_token_structure(plaintext):
    """Validate decrypted token has expected JSON structure."""
    try:
        token_data = json.loads(plaintext.decode('utf-8'))
        required_fields = ['sub', 'exp', 'iat', 'scope']
        for field in required_fields:
            if field not in token_data:
                return None, f"Missing field: {field}"
        return token_data, None
    except (json.JSONDecodeError, UnicodeDecodeError):
        return None, "Malformed token payload"


def lambda_handler(event, context):
    """AWS Lambda handler for token decryption service.
    Expects POST with JSON body: {"token": "<base64-encoded-ciphertext>"}
    """
    try:
        # Parse request body
        if event.get('isBase64Encoded'):
            body = base64.b64decode(event['body']).decode('utf-8')
        else:
            body = event.get('body', '{}')

        request = json.loads(body)
        token_b64 = request.get('token')

        if not token_b64:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Missing token parameter'})
            }

        # Attempt decryption
        try:
            plaintext = decrypt_token(token_b64)
        except ValueError as e:
            error_msg = str(e)
            # Differentiated error responses for debugging
            if "Padding" in error_msg or "padding" in error_msg:
                return {
                    'statusCode': 400,
                    'body': json.dumps({'error': 'Token integrity check failed', 'code': 'PADDING_ERROR'})
                }
            elif "length" in error_msg.lower():
                return {
                    'statusCode': 400,
                    'body': json.dumps({'error': 'Invalid token format', 'code': 'FORMAT_ERROR'})
                }
            else:
                return {
                    'statusCode': 400,
                    'body': json.dumps({'error': 'Decryption failed', 'code': 'DECRYPT_ERROR'})
                }

        # Validate token structure
        token_data, validation_error = validate_token_structure(plaintext)
        if validation_error:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': validation_error, 'code': 'VALIDATION_ERROR'})
            }

        return {
            'statusCode': 200,
            'body': json.dumps({
                'valid': True,
                'claims': token_data
            })
        }

    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': 'Internal server error'})
        }
